        while (bb.hasRemaining()) {
            int b = bb.get() & 0xFF;
            if (b < 0x80) {
                sb.append((char) b);
            } else if ((b & 0xE0) == 0xC0) {
                int c = ((b & 0x1F) << 6) | (bb.get() & 0x3F);
                sb.append((char) c);
            } else if ((b & 0xF0) == 0xE0) {
                int c = ((b & 0x0F) << 12) | ((bb.get() & 0x3F) << 6) | (bb.get() & 0x3F);
                sb.append((char) c);
            } else if ((b & 0xF8) == 0xF0) {
                int c = ((b & 0x07) << 18) | ((bb.get() & 0x3F) << 12) | ((bb.get() & 0x3F) << 6) | (bb.get() & 0x3F);
                sb.append((char) c);
            } else {
                // Invalid UTF-8 sequence
                return -1;
            }
