private static String substVars(String value, Properties props) {
    StringBuilder buf = new StringBuilder();
    int start = 0;
    while (start < value.length()) {
        int idx = value.indexOf("${", start);
        if (idx == -1) {
            buf.append(value.substring(start));
            break;
        }
        buf.append(value.substring(start, idx));
        int end = value.indexOf("}", idx);
        if (end == -1) {
            buf.append(value.substring(idx));
            break;
        }
        String varName = value.substring(idx + 2, end);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            buf.append(varValue);
        } else {
            buf.append("${").append(varName).append("}");
        }
        start = end + 1;
    }
    return buf.toString();
}
