public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("Desired capacity must be greater than 0");
    }

    int capacity = desiredCapacity;
    boolean found = false;

    while (!found) {
        if (isPrime(capacity)) {
            found = true;
        } else {
            capacity++;
        }

        if (desiredCapacity >= 1000 && capacity - desiredCapacity > desiredCapacity * 0.11) {
            capacity = desiredCapacity + (int) (desiredCapacity * 0.11);
        }
    }

    return capacity;
}

private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    if (number <= 3) {
        return true;
    }
    if (number % 2 == 0 || number % 3 == 0) {
        return false;
    }
    for (int i = 5; i * i <= number; i += 6) {
        if (number % i == 0 || number % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}
