        char ch = input.charAt(currentChar);
        if (isTerminator(ch, terminators)) {
            break;
        }
        token.append(ch);
        currentChar++;
    }

    return token.toString();
}

private boolean isTerminator(char ch, final char[] terminators) {
    for (char terminator : terminators) {
